package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;
import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.LocalDate;import java.util.*;

@Service public class SupplierPaymentService{
 private static final Set<Integer>SIZES=Set.of(5,10,25,50,100);private static final Set<MedioPagoMovimiento>METHODS=Set.of(MedioPagoMovimiento.CASH,MedioPagoMovimiento.BANK_TRANSFER,MedioPagoMovimiento.CHECK,MedioPagoMovimiento.CARD,MedioPagoMovimiento.OTHER);
 private final SupplierPaymentRepository payments;private final SupplierPaymentApplicationRepository applications;private final SupplierPaymentDraftAllocationRepository drafts;private final FinancialMovementRepository movements;private final CuentaDineroResolver accountResolver;private final CashRegisterSessionService cashSessions;private final AuditoriaService audit;private final SupplierRepository suppliers;private final MonedaRepository currencies;private final PurchaseInvoiceRepository invoices;private final AccountsPayableRepository payables;private final SupplierCreditNoteRepository creditNotes;private final SupplierPaymentNumberService numbers;private final BankReconciliationMatchRepository reconciliation;
 public SupplierPaymentService(SupplierPaymentRepository payments,SupplierPaymentApplicationRepository applications,SupplierPaymentDraftAllocationRepository drafts,FinancialMovementRepository movements,CuentaDineroResolver accountResolver,CashRegisterSessionService cashSessions,AuditoriaService audit,SupplierRepository suppliers,MonedaRepository currencies,PurchaseInvoiceRepository invoices,AccountsPayableRepository payables,SupplierCreditNoteRepository creditNotes,SupplierPaymentNumberService numbers,BankReconciliationMatchRepository reconciliation){this.payments=payments;this.applications=applications;this.drafts=drafts;this.movements=movements;this.accountResolver=accountResolver;this.cashSessions=cashSessions;this.audit=audit;this.suppliers=suppliers;this.currencies=currencies;this.invoices=invoices;this.payables=payables;this.creditNotes=creditNotes;this.numbers=numbers;this.reconciliation=reconciliation;}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.ver')")
 public Page<PagoProveedorDto> search(String q,UUID supplier,EstadoPagoProveedor state,MedioPagoMovimiento method,UUID currency,LocalDate from,LocalDate to,int page,int size){page(page,size);if(from!=null&&to!=null&&to.isBefore(from))throw new ReglaNegocioException("La fecha final no puede ser anterior a la inicial.");var p=TenantContext.principalActual();return payments.buscar(p.tenantId(),p.empresaId(),clean(q),supplier,state,method,currency,from,to,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"fecha","numero"))).map(x->map(x,false));}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.ver')") public PagoProveedorDto get(UUID id){return map(safe(id),true);}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAnyAuthority('pagos_proveedores.ver','pagos_proveedores.crear','pagos_proveedores.editar')")
 public PagoProveedorCatalogosDto catalogs(){var p=TenantContext.principalActual();var ps=suppliers.buscar(p.tenantId(),p.empresaId(),"","",true,PageRequest.of(0,100,Sort.by("nombreComercial"))).stream().map(x->new PagoProveedorCatalogosDto.Opcion(x.getId(),x.getNombreComercial())).toList();var ms=currencies.findAllByEmpresaIdAndActivoTrueOrderByCodigoIso(p.empresaId()).stream().map(x->new PagoProveedorCatalogosDto.Opcion(x.getId(),x.getCodigoIso()+" · "+x.getNombre())).toList();UUID base=currencies.findByEmpresaIdAndMonedaBaseTrue(p.empresaId()).filter(Moneda::isActivo).map(Moneda::getId).orElse(null);return new PagoProveedorCatalogosDto(ps,ms,base);}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAnyAuthority('pagos_proveedores.crear','pagos_proveedores.editar','pagos_proveedores.aplicar')") public List<CuentaDineroOpcionDto> sources(TipoCuentaDinero type,UUID currency,String filter,int offset,int limit){return accountResolver.buscarFuentesPago(type,currency,filter,offset,limit);}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAnyAuthority('pagos_proveedores.crear','pagos_proveedores.editar','pagos_proveedores.aplicar')")
 public Page<FacturaAplicacionCreditoDto> pendingInvoices(UUID supplier,UUID currency,String q,int page,int size){page(page,size);var p=TenantContext.principalActual();return invoices.buscarPendientesParaAplicar(p.tenantId(),p.empresaId(),supplier,currency,clean(q),PageRequest.of(page,size,Sort.by("vencimiento","fecha","numeroInterno"))).map(this::invoiceOption);}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAnyAuthority('pagos_proveedores.crear','pagos_proveedores.editar')") public CreditosProveedorDto credits(UUID supplier,UUID currency){var p=TenantContext.principalActual();if(supplier==null||currency==null)return new CreditosProveedorDto(BigDecimal.ZERO,BigDecimal.ZERO);return new CreditosProveedorDto(creditNotes.disponibleProveedor(p.tenantId(),p.empresaId(),supplier,currency),payments.disponibleProveedor(p.tenantId(),p.empresaId(),supplier,currency));}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.aplicar')") public List<PagoProveedorInput.Aplicacion> propose(UUID id){PagoProveedor payment=safe(id);return propose(payment.getProveedorId(),payment.getMonedaId(),payment.disponible());}
 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAnyAuthority('pagos_proveedores.crear','pagos_proveedores.editar')") public List<PagoProveedorInput.Aplicacion> propose(UUID supplier,UUID currency,BigDecimal amount){if(supplier==null||currency==null||amount==null||amount.signum()<=0)return List.of();return proposeInternal(supplier,currency,amount);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.crear')") public PagoProveedorDto create(PagoProveedorInput input){Validated v=validate(input,null);var p=TenantContext.principalActual();UUID key=input.claveIdempotencia()==null?UUID.randomUUID():input.claveIdempotencia();var duplicate=payments.findByClaveIdempotenciaAndTenantIdAndEmpresaId(key,p.tenantId(),p.empresaId());if(duplicate.isPresent())return map(duplicate.get(),true);PagoProveedor payment=new PagoProveedor(p.tenantId(),p.empresaId(),numbers.next(p.tenantId(),p.empresaId()),v.supplier().getId(),input.fecha(),v.currency().getId(),v.amount(),input.tipoFuente(),input.fuenteId(),v.method(),v.check(),v.reference(),v.notes(),key,p.usuarioId());payment=payments.saveAndFlush(payment);replaceDrafts(payment,v.allocations());audit.registrar("SUPPLIER_PAYMENT_CREATED","PagoProveedor",payment.getId(),detail(payment));return map(payment,true);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.editar')") public PagoProveedorDto update(UUID id,PagoProveedorInput input){PagoProveedor payment=locked(id);draft(payment);expected(payment,input==null?null:input.version());Validated v=validate(input,id);var p=TenantContext.principalActual();payment.actualizar(v.supplier().getId(),input.fecha(),v.currency().getId(),v.amount(),input.tipoFuente(),input.fuenteId(),v.method(),v.check(),v.reference(),v.notes(),p.usuarioId());payments.saveAndFlush(payment);replaceDrafts(payment,v.allocations());audit.registrar("SUPPLIER_PAYMENT_UPDATED","PagoProveedor",payment.getId(),detail(payment));return map(payment,true);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.crear') and hasAuthority('pagos_proveedores.confirmar')") public PagoProveedorDto createAndConfirm(PagoProveedorInput input){PagoProveedorDto created=create(input);return confirm(created.id(),created.version());}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.editar') and hasAuthority('pagos_proveedores.confirmar')") public PagoProveedorDto updateAndConfirm(UUID id,PagoProveedorInput input){PagoProveedorDto updated=update(id,input);return confirm(id,updated.version());}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and @empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('pagos_proveedores.confirmar')")
 public PagoProveedorDto confirm(UUID id,long version){PagoProveedor payment=locked(id);if(payment.getEstado()!=EstadoPagoProveedor.DRAFT)return map(payment,true);expected(payment,version);var p=TenantContext.principalActual();var account=accountResolver.resolver(payment.getTipoFuente(),sourceId(payment));if(!payment.getMonedaId().equals(account.monedaId()))throw new ReglaNegocioException("La moneda de la fuente debe coincidir con la moneda del pago.");UUID session=payment.getTipoFuente()==TipoCuentaDinero.CASH_REGISTER?cashSessions.requerirSesionAbierta(payment.getCajaId()):null;List<DistribucionBorradorPagoProveedor> prepared=drafts.findAllByPagoIdAndTenantIdAndEmpresaId(payment.getId(),p.tenantId(),p.empresaId());BigDecimal total=prepared.stream().map(DistribucionBorradorPagoProveedor::getMonto).reduce(BigDecimal.ZERO,BigDecimal::add);if(total.compareTo(payment.getMonto())>0)throw new ReglaNegocioException("El total aplicado supera el monto del pago.");payment.confirmar(p.usuarioId());payment=payments.saveAndFlush(payment);MovimientoFinanciero movement=MovimientoFinanciero.pagoProveedor(p.tenantId(),p.empresaId(),payment.getFecha(),payment.getTipoFuente(),sourceId(payment),payment.getMonedaId(),payment.getMonto(),"Pago a proveedor "+payment.getNumero(),payment.getReferencia(),payment.getId(),payment.getMedioPago(),session,p.usuarioId());movement.asignarRelacionesCuenta(account.caja(),account.cuentaBancaria(),account.moneda());movement=movements.saveAndFlush(movement);payment.vincularMovimiento(movement.getId());for(var allocation:prepared)applyOne(payment,allocation.getFacturaId(),allocation.getMonto(),p.usuarioId());drafts.deleteAllByPagoIdAndTenantIdAndEmpresaId(payment.getId(),p.tenantId(),p.empresaId());payments.saveAndFlush(payment);audit.registrar("SUPPLIER_PAYMENT_CONFIRMED","PagoProveedor",payment.getId(),detail(payment));return map(payment,true);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.aplicar')") public PagoProveedorDto apply(UUID id,AplicarPagoProveedorInput input){PagoProveedor payment=locked(id);expected(payment,input==null?null:input.version());if(payment.getEstado()==EstadoPagoProveedor.DRAFT||payment.getEstado()==EstadoPagoProveedor.VOIDED||payment.disponible().signum()<=0)throw new ReglaNegocioException("El pago no tiene importe disponible.");List<PagoProveedorInput.Aplicacion> items=validateApplications(input==null?null:input.aplicaciones(),payment.getProveedorId(),payment.getMonedaId(),payment.disponible(),true);UUID user=TenantContext.principalActual().usuarioId();for(var item:items)applyOne(payment,item.facturaId(),item.monto(),user);payments.saveAndFlush(payment);audit.registrar("SUPPLIER_PAYMENT_APPLIED","PagoProveedor",payment.getId(),detail(payment));return map(payment,true);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('COMPRAS') and hasAuthority('pagos_proveedores.anular')") public PagoProveedorDto voidPayment(UUID id,long version,String reason){PagoProveedor payment=locked(id);if(payment.getEstado()==EstadoPagoProveedor.VOIDED)return map(payment,true);if(payment.getEstado()==EstadoPagoProveedor.DRAFT)throw new ReglaNegocioException("Un borrador no requiere anulación.");expected(payment,version);String cleanReason=required(reason,500,"El motivo de anulación es obligatorio.");var p=TenantContext.principalActual();MovimientoFinanciero movement=movements.bloquearPorOrigen(p.tenantId(),p.empresaId(),TipoOrigenMovimiento.SUPPLIER_PAYMENT,payment.getId()).orElseThrow(()->new ReglaNegocioException("No se encontró la salida financiera del pago."));if(reconciliation.existsByMovimientoFinancieroId(movement.getId()))throw new ReglaNegocioException("El pago posee un movimiento conciliado y no puede anularse.");cashSessions.validarMovimientoModificable(movement.getSesionCajaId());for(var app:applications.findAllByPagoIdAndTenantIdAndEmpresaIdAndReversedFalseOrderByAplicadaEn(payment.getId(),p.tenantId(),p.empresaId())){CuentaPagar payable=payables.bloquearPorFactura(app.getFacturaId(),p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("No fue posible revertir una aplicación."));payable.revertirCredito(app.getMonto());payables.save(payable);FacturaProveedor invoice=invoices.bloquear(app.getFacturaId(),p.tenantId(),p.empresaId()).orElseThrow();invoice.actualizarEstadoFinanciero(payable.getEstado(),p.usuarioId());app.revertir(cleanReason,p.usuarioId());applications.save(app);payment.revertir(app.getMonto(),p.usuarioId());}movement.anular(cleanReason,p.usuarioId());movements.saveAndFlush(movement);payment.anular(cleanReason,p.usuarioId());payments.saveAndFlush(payment);audit.registrar("SUPPLIER_PAYMENT_VOIDED","PagoProveedor",payment.getId(),detail(payment));return map(payment,true);}

 @Transactional public PagoProveedor registrar(FacturaProveedor invoice,PagoFacturaProveedorInput input){if(input==null||input.tipoFuente()==null||input.fuenteId()==null)throw new ReglaNegocioException("Selecciona la caja o cuenta bancaria utilizada para pagar la factura.");UUID key=input.claveIdempotencia()==null?UUID.randomUUID():input.claveIdempotencia();var duplicated=payments.findByClaveIdempotenciaAndTenantIdAndEmpresaId(key,invoice.getTenantId(),invoice.getEmpresaId());if(duplicated.isPresent())return duplicated.get();if(payments.findByFacturaIdAndTenantIdAndEmpresaId(invoice.getId(),invoice.getTenantId(),invoice.getEmpresaId()).isPresent())throw new ReglaNegocioException("La factura ya tiene un pago al contado registrado.");var account=accountResolver.resolver(input.tipoFuente(),input.fuenteId());if(!invoice.getMonedaId().equals(account.monedaId()))throw new ReglaNegocioException("La moneda de la fuente de pago debe ser igual a la moneda de la factura.");MedioPagoMovimiento method=normalizeMethod(input.tipoFuente(),input.medioPago());UUID session=input.tipoFuente()==TipoCuentaDinero.CASH_REGISTER?cashSessions.requerirSesionAbierta(input.fuenteId()):null;var p=TenantContext.principalActual();PagoProveedor payment=new PagoProveedor(invoice.getTenantId(),invoice.getEmpresaId(),numbers.next(invoice.getTenantId(),invoice.getEmpresaId()),invoice.getProveedorId(),invoice.getFecha(),invoice.getMonedaId(),invoice.getTotal(),input.tipoFuente(),input.fuenteId(),method,null,clean(input.referencia()),"Pago al contado de factura "+invoice.getNumeroProveedor(),key,p.usuarioId());payment.vincularFacturaContado(invoice.getId(),null);payment.confirmar(p.usuarioId());payment.aplicar(invoice.getTotal(),p.usuarioId());payment=payments.saveAndFlush(payment);MovimientoFinanciero movement=MovimientoFinanciero.pagoProveedor(invoice.getTenantId(),invoice.getEmpresaId(),invoice.getFecha(),input.tipoFuente(),input.fuenteId(),invoice.getMonedaId(),invoice.getTotal(),"Pago factura proveedor "+invoice.getNumeroProveedor(),clean(input.referencia()),payment.getId(),method,session,p.usuarioId());movement.asignarRelacionesCuenta(account.caja(),account.cuentaBancaria(),account.moneda());movement=movements.saveAndFlush(movement);payment.vincularMovimiento(movement.getId());payments.saveAndFlush(payment);audit.registrar("SUPPLIER_PAYMENT_CREATED","PagoProveedor",payment.getId(),detail(payment));return payment;}
 @Transactional public void anularPorFactura(FacturaProveedor invoice,String reason){PagoProveedor payment=payments.bloquearPorFactura(invoice.getId(),invoice.getTenantId(),invoice.getEmpresaId()).orElse(null);if(payment==null||payment.getEstado()==EstadoPagoProveedor.VOIDED)return;MovimientoFinanciero movement=movements.bloquearPorOrigen(invoice.getTenantId(),invoice.getEmpresaId(),TipoOrigenMovimiento.SUPPLIER_PAYMENT,payment.getId()).orElseThrow(()->new ReglaNegocioException("No se encontró el movimiento financiero asociado al pago."));if(movement.getSesionCajaId()!=null)cashSessions.validarMovimientoModificable(movement.getSesionCajaId());UUID user=TenantContext.principalActual().usuarioId();movement.anular(reason,user);movements.saveAndFlush(movement);payment.anular(reason,user);payments.saveAndFlush(payment);audit.registrar("SUPPLIER_PAYMENT_VOIDED","PagoProveedor",payment.getId(),detail(payment));}

 private Validated validate(PagoProveedorInput input,UUID current){if(input==null)throw new ReglaNegocioException("Los datos del pago son obligatorios.");var p=TenantContext.principalActual();Proveedor supplier=suppliers.findByIdAndTenantIdAndEmpresaId(input.proveedorId(),p.tenantId(),p.empresaId()).filter(Proveedor::isActivo).orElseThrow(()->new ReglaNegocioException("El proveedor seleccionado no está disponible."));if(input.fecha()==null)throw new ReglaNegocioException("La fecha es obligatoria.");Moneda currency=currencies.findByIdAndEmpresaId(input.monedaId(),p.empresaId()).filter(Moneda::isActivo).orElseThrow(()->new ReglaNegocioException("La moneda no está disponible."));BigDecimal amount=input.monto();if(amount==null||amount.signum()<=0)throw new ReglaNegocioException("El monto del pago debe ser mayor que cero.");if(input.tipoFuente()==null||input.fuenteId()==null)throw new ReglaNegocioException("Selecciona la caja o cuenta de salida.");MedioPagoMovimiento method=normalizeMethod(input.tipoFuente(),input.medioPago());var account=accountResolver.resolver(input.tipoFuente(),input.fuenteId());if(!currency.getId().equals(account.monedaId()))throw new ReglaNegocioException("La moneda de la fuente debe coincidir con la moneda del pago.");String check=method==MedioPagoMovimiento.CHECK?required(input.numeroCheque(),50,"El número de cheque es obligatorio."):optional(input.numeroCheque(),50);String reference=optional(input.referencia(),100),notes=optional(input.observacion(),1000);List<PagoProveedorInput.Aplicacion> allocations=validateApplications(input.aplicaciones(),supplier.getId(),currency.getId(),amount,false);if(method==MedioPagoMovimiento.CHECK&&payments.existeChequeActivo(p.tenantId(),p.empresaId(),input.fuenteId(),check,EstadoPagoProveedor.VOIDED,current))throw new ReglaNegocioException("Ya existe un pago activo con ese número de cheque.");return new Validated(supplier,currency,amount,method,check,reference,notes,allocations);}
 private List<PagoProveedorInput.Aplicacion> validateApplications(List<PagoProveedorInput.Aplicacion> requested,UUID supplier,UUID currency,BigDecimal limit,boolean required){List<PagoProveedorInput.Aplicacion> items=requested==null?List.of():requested;if(required&&items.isEmpty())throw new ReglaNegocioException("Selecciona al menos una factura e importe.");Set<UUID> unique=new HashSet<>();BigDecimal total=BigDecimal.ZERO;for(var item:items){if(item==null||item.facturaId()==null||item.monto()==null||item.monto().signum()<=0)throw new ReglaNegocioException("Los importes a aplicar deben ser mayores que cero.");if(!unique.add(item.facturaId()))throw new ReglaNegocioException("La factura está repetida en la distribución.");FacturaProveedor invoice=invoice(item.facturaId());if(!invoice.getProveedorId().equals(supplier)||!invoice.getMonedaId().equals(currency))throw new ReglaNegocioException("Las facturas deben corresponder al proveedor y moneda del pago.");CuentaPagar payable=payables.findByFacturaIdAndTenantIdAndEmpresaId(invoice.getId(),invoice.getTenantId(),invoice.getEmpresaId()).filter(c->!c.isAnulada()).orElseThrow(()->new ReglaNegocioException("La factura no tiene saldo pendiente."));if(item.monto().compareTo(payable.saldo())>0)throw new ReglaNegocioException("El importe supera el saldo actual de la factura "+invoice.getNumeroInterno()+".");total=total.add(item.monto());}if(total.compareTo(limit)>0)throw new ReglaNegocioException("El total aplicado supera el importe disponible del pago.");return List.copyOf(items);}
 private void replaceDrafts(PagoProveedor payment,List<PagoProveedorInput.Aplicacion> values){drafts.deleteAllByPagoIdAndTenantIdAndEmpresaId(payment.getId(),payment.getTenantId(),payment.getEmpresaId());drafts.flush();drafts.saveAll(values.stream().map(x->new DistribucionBorradorPagoProveedor(payment.getTenantId(),payment.getEmpresaId(),payment.getId(),x.facturaId(),x.monto())).toList());}
 private void applyOne(PagoProveedor payment,UUID invoiceId,BigDecimal amount,UUID user){var p=TenantContext.principalActual();CuentaPagar payable=payables.bloquearPorFactura(invoiceId,p.tenantId(),p.empresaId()).filter(c->!c.isAnulada()).orElseThrow(()->new ReglaNegocioException("La factura ya no tiene saldo disponible."));if(!payable.getProveedorId().equals(payment.getProveedorId())||!payable.getMonedaId().equals(payment.getMonedaId()))throw new ReglaNegocioException("La factura no corresponde al proveedor y moneda del pago.");BigDecimal previousBalance=payable.saldo();if(amount.compareTo(previousBalance)>0)throw new ReglaNegocioException("El saldo de la factura cambió. Saldo actual: "+previousBalance.setScale(2,RoundingMode.HALF_UP)+".");if(amount.compareTo(payment.disponible())>0)throw new ReglaNegocioException("El importe disponible del pago cambió.");payable.aplicarCredito(amount);BigDecimal remainingBalance=payable.saldo();payables.save(payable);FacturaProveedor invoice=invoices.bloquear(invoiceId,p.tenantId(),p.empresaId()).orElseThrow();invoice.actualizarEstadoFinanciero(payable.getEstado(),user);applications.saveAndFlush(new AplicacionPagoProveedor(p.tenantId(),p.empresaId(),payment.getId(),invoiceId,payable.getId(),amount,previousBalance,remainingBalance,user));payment.aplicar(amount,user);payments.save(payment);audit.registrar("SUPPLIER_PAYMENT_APPLICATION_CREATED","AplicacionPagoProveedor",payment.getId(),"{\"facturaId\":\""+invoiceId+"\",\"monto\":"+amount+",\"saldoAnterior\":"+previousBalance+",\"saldoRestante\":"+remainingBalance+"}");}
 private List<PagoProveedorInput.Aplicacion> proposeInternal(UUID supplier,UUID currency,BigDecimal available){var p=TenantContext.principalActual();BigDecimal remaining=available;List<PagoProveedorInput.Aplicacion> result=new ArrayList<>();for(CuentaPagar payable:payables.pendientes(p.tenantId(),p.empresaId(),supplier,currency)){if(remaining.signum()<=0)break;BigDecimal amount=payable.saldo().min(remaining);result.add(new PagoProveedorInput.Aplicacion(payable.getFacturaId(),amount));remaining=remaining.subtract(amount);}return result;}
 private PagoProveedorDto map(PagoProveedor payment,boolean detail){var p=TenantContext.principalActual();List<AplicacionPagoProveedorDto> apps;if(payment.getEstado()==EstadoPagoProveedor.DRAFT&&detail)apps=drafts.findAllByPagoIdAndTenantIdAndEmpresaId(payment.getId(),p.tenantId(),p.empresaId()).stream().map(d->applicationDto(d.getId(),d.getFacturaId(),null,d.getMonto())).toList();else apps=detail?applications.findAllByPagoIdAndTenantIdAndEmpresaIdAndReversedFalseOrderByAplicadaEn(payment.getId(),p.tenantId(),p.empresaId()).stream().map(a->applicationDto(a.getId(),a.getFacturaId(),a.getAplicadaEn(),a.getMonto())).toList():List.of();String source=payment.getCaja()!=null?payment.getCaja().getNombre():payment.getCuentaBancaria()!=null?payment.getCuentaBancaria().getBancoNombre()+" · "+payment.getCuentaBancaria().getNombreCuenta():"—";return new PagoProveedorDto(payment.getId(),payment.getNumero(),payment.getProveedorId(),payment.getProveedor()==null?"—":payment.getProveedor().getNombreComercial(),payment.getProveedor()==null?null:payment.getProveedor().getIdentificacionFiscal(),payment.getFecha(),payment.getMonedaId(),payment.getMoneda()==null?"—":payment.getMoneda().getCodigoIso(),payment.getMonto(),payment.getMontoAplicado(),payment.disponible(),payment.getMedioPago(),payment.getTipoFuente(),sourceId(payment),source,payment.getNumeroCheque(),payment.getReferencia(),payment.getNotas(),payment.getEstado(),payment.getVersion(),apps,payment.getMotivoAnulacion());}
 private AplicacionPagoProveedorDto applicationDto(UUID id,UUID invoiceId,java.time.OffsetDateTime date,BigDecimal amount){var p=TenantContext.principalActual();FacturaProveedor invoice=invoices.findByIdAndTenantIdAndEmpresaId(invoiceId,p.tenantId(),p.empresaId()).orElse(null);return new AplicacionPagoProveedorDto(id,invoiceId,invoice==null?"—":invoice.getNumeroInterno(),invoice==null?"—":invoice.getNumeroProveedor(),date,amount);}
 private FacturaAplicacionCreditoDto invoiceOption(FacturaProveedor f){CuentaPagar c=payables.findByFacturaIdAndTenantIdAndEmpresaId(f.getId(),f.getTenantId(),f.getEmpresaId()).orElse(null);return new FacturaAplicacionCreditoDto(f.getId(),f.getNumeroInterno(),f.getNumeroProveedor(),f.getNumeroFiscal(),f.getFecha(),f.getVencimiento(),f.getMonedaId(),f.getMoneda()==null?null:f.getMoneda().getCodigoIso(),f.getTotal(),c==null?BigDecimal.ZERO:c.getMontoAplicado(),BigDecimal.ZERO,c==null?BigDecimal.ZERO:c.saldo());}
 private PagoProveedor safe(UUID id){var p=TenantContext.principalActual();return payments.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Pago no encontrado."));}private PagoProveedor locked(UUID id){var p=TenantContext.principalActual();return payments.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Pago no encontrado."));}private FacturaProveedor invoice(UUID id){var p=TenantContext.principalActual();return invoices.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).filter(f->f.getEstado()==EstadoFacturaProveedor.REGISTERED).orElseThrow(()->new ReglaNegocioException("La factura no está disponible."));}
 private static UUID sourceId(PagoProveedor p){return p.getTipoFuente()==TipoCuentaDinero.CASH_REGISTER?p.getCajaId():p.getCuentaBancariaId();}private static void draft(PagoProveedor p){if(p.getEstado()!=EstadoPagoProveedor.DRAFT)throw new ReglaNegocioException("Solo se pueden editar pagos en borrador.");}private static void expected(PagoProveedor p,Long version){if(version==null||p.getVersion()!=version)throw new ReglaNegocioException("El pago fue modificado por otro usuario. Actualiza la pantalla.");}
 private static MedioPagoMovimiento normalizeMethod(TipoCuentaDinero type,MedioPagoMovimiento method){if(type==TipoCuentaDinero.CASH_REGISTER){if(method!=null&&method!=MedioPagoMovimiento.CASH)throw new ReglaNegocioException("Las cajas solo admiten pagos en efectivo.");return MedioPagoMovimiento.CASH;}if(method==null||!METHODS.contains(method)||method==MedioPagoMovimiento.CASH)throw new ReglaNegocioException("Selecciona un medio de pago bancario válido.");return method;}
 private static void page(int page,int size){if(page<0||!SIZES.contains(size))throw new ReglaNegocioException("Paginación inválida.");}private static String clean(String s){return s==null?"":s.trim();}private static String optional(String s,int max){String v=clean(s);if(v.isEmpty())return null;if(v.length()>max)throw new ReglaNegocioException("El valor excede "+max+" caracteres.");return v;}private static String required(String s,int max,String message){String v=clean(s);if(v.isEmpty())throw new ReglaNegocioException(message);if(v.length()>max)throw new ReglaNegocioException("El valor excede "+max+" caracteres.");return v;}private static String detail(PagoProveedor p){return "{\"numero\":\""+p.getNumero()+"\",\"monto\":"+p.getMonto()+",\"aplicado\":"+p.getMontoAplicado()+"}";}
 private record Validated(Proveedor supplier,Moneda currency,BigDecimal amount,MedioPagoMovimiento method,String check,String reference,String notes,List<PagoProveedorInput.Aplicacion> allocations){}
}
